Definition cnt_tbs (m : word -> option byte) (tab o : Z) : list byte :=
  match rdn SEGS m (Z_to_bv 64 (tab + o)) 4 with Some bs => bs | None => [] end.
Definition cnt_tvs (m : word -> option byte) (tab o : Z) : word := Z_to_bv 64 (bytes_le_to_Z (cnt_tbs m tab o)).
Lemma cnt_tab_rd : forall C A m md (tab : Z), Cok C -> W C A m md -> live A (Z_to_bv 64 tab) = Some 1024%Z -> (0 <= tab)%Z -> (tab + 1024 < 2 ^ 64)%Z ->
