(* [comment removed for export] *)
Section Tab4.
Variables (C : lctx) (A0 A : AS) (md : Model) (mB : word -> option byte) (s tab : Z) (S : TSet).
Hypothesis CK : Cok C.
Hypothesis SUB : sub_live A0 A.
Hypothesis Lt : live A (Z_to_bv 64 tab) = Some 1024%Z.
Hypothesis Ltr : live A0 (Z_to_bv 64 tab) = None.
Hypothesis Lt0 : live (c_A0 C) (Z_to_bv 64 tab) = None.
Hypothesis Htab : (0 <= tab < 2 ^ 64)%Z.
Definition FTc (m : word -> option byte) : Prop := forall a : word, ~ (tab <= u a < tab + 1024)%Z -> m a = mB a.
Lemma cp_tab_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (k : Z),
  W C A m md -> POSTM C A0 s mB m -> FTc m -> (0 <= k)%Z -> (Z.of_nat n = 255 - k)%Z ->
  regs_agree (fun x => In x [5; 6; 7; 10; 12; 13; 14; 15; 16; 17]%list) r0 r ->
  getr r 12 = Z_to_bv 64 (tab + 4 * k) -> getr r 11 = Z_to_bv 64 (tab + 1024) ->
  (forall m' r', W C A m' md -> POSTM C A0 s mB m' -> FTc m' ->
     regs_agree (fun x => In x [5; 6; 7; 10; 12; 13; 14; 15; 16; 17]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x79084 : word) m' al_rom) md) S) ->
