Section Rows.
Variables (C : lctx) (A : AS) (md : Model) (m : word -> option byte) (data wpl h kd tab fw eb : Z) (S : TSet).
Hypothesis CK : Cok C.
Hypothesis HW : W C A m md.
Hypothesis Ld : live A (Z_to_bv 64 data) = Some kd.
Hypothesis Hkd : (4 * wpl * h <= kd)%Z.
Hypothesis Lt : live A (Z_to_bv 64 tab) = Some 1024%Z.
Hypothesis Hdd : (0 <= data < 2 ^ 64)%Z.
Hypothesis Htab : (0 <= tab < 2 ^ 64)%Z.
Hypothesis Hh : (1 <= h < 2 ^ 24)%Z.
Hypothesis Hwpl : (1 <= wpl < 2 ^ 24)%Z.
Hypothesis Hfw : (0 <= fw <= wpl)%Z.
Hypothesis Heb : (0 <= eb < 32)%Z.
Hypothesis Hfe : (1 <= eb -> fw + 1 <= wpl)%Z.
Hypothesis Hf0 : (fw = 0 -> 1 <= eb)%Z.

Lemma cp_facts : (0 < kd)%Z /\ (4096 <= data)%Z /\ (data + kd <= alloc_top (c_vm C))%Z /\ (4096 <= tab)%Z /\ (tab + 1024 <= alloc_top (c_vm C))%Z
