(* [comment removed for export] *)
Lemma cp_eb_W : forall (r0 r : bvmap 5 word) (i : Z),
  (0 <= i < h)%Z -> (1 <= eb)%Z -> regs_agree (fun x => In x [7; 14; 19; 28; 29; 30; 31]%list) r0 r ->
  getr r 7 = Z_to_bv 64 fw -> getr r 6 = Z_to_bv 64 (data + 4 * wpl * i) -> getr r 18 = Z_to_bv 64 tab ->
  (forall r', regs_agree (fun x => In x [7; 14; 19; 28; 29; 30; 31]%list) r0 r' -> realizes SEGS (mkCfg (mkst r' (0x790ec : word) m al_rom) md) S) ->
